-- ROLLBACK for 20261005173100_fll_tp_rhizom_followup_hints.sql — restores the pre-block descriptions (inventory snapshot 20261005).
BEGIN;
UPDATE fields x SET description = 'Plan B fllwave P-21 / Ruling H-2: Werkstoffklasse für die Wahl des Nachweiswegs auf FLLTP-RHZ-03. TP §1 nennt als werkstoffspezifisch wurzel- und rhizomfest "z. B. Stahl, Beton, PEHD" (offene Aufzählung — "sonstige" verlangt auf dem werkstoffspezifischen Weg eine Begründung, nachweis_begruendung). GUP nach FLL GA-RL 2023 §7.3.1.1 (Verweis, final review I-2); REQ-RHZ03-WERKSTOFF (warn) meldet "sonstige" auf dem werkstoffspezifischen Weg.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-02' AND x.symbol = 'werkstoff_klasse';
UPDATE fields x SET description = 'Plan B fllwave P-20 / Ruling H-2: Hauptschalter. "pruefung" = Prüfung nach dem FLL-Verfahren (die Laborblätter FLLTP-RHZ-04…20, die Prüfauftragsfelder auf -01 und die Bescheinigungsfelder auf -21 sind nur dann sichtbar). "werkstoffspezifisch" = werkstoffspezifisch wurzel- und rhizomfest nach TP §1, kein gesonderter Nachweis nach FLL-Prüfverfahren; Konformität auf -21 dann "werkstoffspezifisch_rhizomfest". Der Vorwort-Weg (Dachbegrünungsprüfung, geringe Beanspruchung) ist nicht abgebildet (fllwave-H-3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-03' AND x.symbol = 'nachweis_route';
UPDATE fields x SET description = 'Plan B fllwave P-20: nur sichtbar (und dann Pflicht), wenn nachweis_route = werkstoffspezifisch. TP §1 zählt die Werkstoffe nur beispielhaft auf ("z. B."); die Begründung nennt Werkstoff und Grundlage.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-03' AND x.symbol = 'nachweis_begruendung';
UPDATE fields x SET description = 'Plan B fllwave P-20: nur sichtbar (und dann Pflicht) auf dem werkstoffspezifischen Weg; "ja" löst die Warnung REQ-RHZ03-INTENSIV aus (TP §1: Prüfung nach dem FLL-Verfahren erforderlich).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-03' AND x.symbol = 'intensive_bepflanzung';
UPDATE compliance_requirements x SET description = 'FLL TP Rhizom 2023 (Plan B fllwave P-20, imported_unverified), §1 (PDF p. 8, printed 7): "Bei intensiverer Beanspruchung durch die Bepflanzung (z. B. Vegetation für Pflanzenkläranlagen und Aufbereitungsbereiche von Schwimmteichen) ist eine Prüfung nach dem nachfolgend beschriebenen „Verfahren zur Bestimmung der Rhizomfestigkeit von Gewässerabdichtungen“ der FLL erforderlich." Reference only: FLL GA-RL 2023 §6.4.1.1 (PDF p. 97, printed 95) "Kunststoffbahnen aus PEHD besitzen eine ausreichende Widerstandsfähigkeit gegenüber Wurzeln und Rhizomen. Auf eine Prüfung der Wurzel- und Rhizomfestigkeit kann verzichtet werden." Warn only: whether that waiver overrides TP §1 for PEHD is the specialist planner''s / owner''s decision.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-03' AND x.code = 'REQ-RHZ03-INTENSIV';
UPDATE compliance_requirements x SET description = 'FLL TP Rhizom 2023 (Plan B fllwave final review I-2, imported_unverified), §1 (PDF p. 8, printed 7): "Abdichtungen, die aufgrund ihrer werkstoffspezifischen Eigenschaften als wurzel- und rhizomfest gelten (z. B. Stahl, Beton, PEHD), erfordern keinen gesonderten Nachweis nach FLL-Prüfverfahren." Reference only: FLL GA-RL 2023 §7.3.1.1 (PDF p. 108, printed 106) "Abdichtungen aus GUP besitzen eine ausreichende Widerstandsfähigkeit gegenüber Wurzeln und Rhizomen." and §6.4.1.1 (PDF p. 97, printed 95) "Bei Kunststoffbahnen aus PELD ist vom Hersteller zusätzlich ein Nachweis der Wurzel- bzw. Rhizomfestigkeit gemäß FLL zu erbringen." Warn only: the TP list is open ("z. B.") — a "sonstige" material on the material-based route needs the specialist planner''s / owner''s review.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-03' AND x.code = 'REQ-RHZ03-WERKSTOFF';
UPDATE compliance_requirements x SET title_de = 'Endkonformitaet muss "rhizomfest" sein', title_en = 'Final conformity must be "rhizomfest"' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-21' AND x.code = 'REQ-RHZ21-CONFORMITY' AND x.title_de LIKE 'Endkonformität: "rhizomfest" (Prüfweg)%';
COMMIT;
